def investigate(context, acquire):
    receipts = context.get('receipts', [])
    seen = set()
    for row in receipts:
        query = row.get('query')
        if isinstance(query, dict):
            key = tuple(sorted((a.get('op'), a.get('id')) for a in query.get('actions', [])))
            seen.add(key)
    actions = [{'op': 'put', 'id': 5}, {'op': 'begin'}, {'op': 'put', 'id': 2}, {'op': 'rollback'}]
    key = tuple(sorted((a.get('op'), a.get('id')) for a in actions))
    if key in seen:
        actions = [{'op': 'put', 'id': 1}, {'op': 'begin'}, {'op': 'put', 'id': 3}, {'op': 'rollback'}]
    return {'query': {'actions': actions}, 'note': {'hypothesis': 'AUTOINCREMENT sqlite_sequence is transaction durable; rollback does not lower the high-water mark'}}

